package com.gerenciadorrural.modules.herd.api;
import com.gerenciadorrural.modules.herd.application.ManageHerdReproduction; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/herd") public class HerdReproductionController {private final ManageHerdReproduction s;public HerdReproductionController(ManageHerdReproduction s){this.s=s;}@PostMapping("/animals/{motherId}/breedings")ResponseEntity<?> breed(@ResolvedTenantContext TenantContext c,@PathVariable UUID motherId,@RequestBody BreedingRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.breed(c,motherId,new ManageHerdReproduction.Breeding(r.operationId(),r.expectedVersion(),r.serviceType(),r.serviceOn(),r.sireReference(),r.expectedCalvingOn(),r.notes())));}@PostMapping("/animals/{motherId}/calvings")ResponseEntity<?> calve(@ResolvedTenantContext TenantContext c,@PathVariable UUID motherId,@RequestBody CalvingRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.calve(c,motherId,new ManageHerdReproduction.Calving(r.operationId(),r.expectedVersion(),r.pregnancyId(),r.expectedPregnancyVersion(),r.calvedOn(),r.calfId(),r.identification(),r.name(),r.sex(),r.birthDate())));}@PostMapping("/pregnancies/{id}/confirmation")ResponseEntity<?> confirm(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody TransitionRequest r){return ResponseEntity.ok().body(s.confirm(c,id,new ManageHerdReproduction.Transition(r.operationId(),r.expectedVersion(),r.occurredOn())));}@PostMapping("/pregnancies/{id}/termination")ResponseEntity<?> terminate(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody TerminationRequest r){return ResponseEntity.ok().body(s.terminate(c,id,new ManageHerdReproduction.Transition(r.operationId(),r.expectedVersion(),r.endedOn()),r.reason()));}public record BreedingRequest(UUID operationId,long expectedVersion,ReproductionServiceType serviceType,LocalDate serviceOn,String sireReference,LocalDate expectedCalvingOn,String notes){}public record CalvingRequest(UUID operationId,long expectedVersion,UUID pregnancyId,Long expectedPregnancyVersion,LocalDate calvedOn,UUID calfId,String identification,String name,HerdAnimalSex sex,LocalDate birthDate){}public record TransitionRequest(UUID operationId,long expectedVersion,LocalDate occurredOn){}public record TerminationRequest(UUID operationId,long expectedVersion,LocalDate endedOn,PregnancyTerminationReason reason){}}
